import{_ as s,c as t,o as n,j as i,Y as o,t as r}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"ip-macsec | x-cmd man (ip man8) | MACsec device configuration","titleTemplate":false,"description":"x-cmd man (ip man8 Manual Page) | ip-macsec - MACsec device configuration","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ip-macsec | x-cmd man (ip man8) | MACsec device configuration"}],["meta",{"name":"og:description","content":"x-cmd man (ip man8 Manual Page) | ip-macsec - MACsec device configuration"}]]},"headers":[],"params":{"isMan":true,"man":"ip-macsec","category":"ip man8","desc":"MACsec device configuration"},"relativePath":"ip/man8/ip-macsec.md","filePath":"ip/man8/[man].md"}'),c={name:"ip/man8/ip-macsec.md"},d={class:"visually-hidden"};function l(a,e,g,h,p,m){return n(),t("div",null,[i("h1",d,r(a.$params.man),1),e[0]||(e[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ip-macsec - MACsec device configuration</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ip link add link</strong> <em>DEVICE</em>* * name** <em>NAME</em>* * type macsec ** [ [ <strong>address</strong> * &lt;lladdr&gt;* ] <strong>port</strong> * PORT* | <strong>sci</strong> * &lt;u64&gt;* ] [ <strong>cipher</strong> { <strong>default</strong> | <strong>gcm-aes-128</strong> | <strong>gcm-aes-256</strong> | <strong>gcm-aes-xpn-128</strong> | <strong>gcm-aes-xpn-256</strong> } ] [ <strong>icvlen</strong> * ICVLEN* ] [ <strong>encrypt</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>send_sci</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>end_station</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>scb</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>protect</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>replay</strong> { <strong>on</strong> | <strong>off</strong> } ] [ <strong>window</strong> * WINDOW* ] [ <strong>validate</strong> { <strong>strict</strong> | <strong>check</strong> | <strong>disabled</strong> } ] [ <strong>encodingsa</strong> * SA* ] [ <strong>offload</strong> { <strong>off</strong> | <strong>phy</strong> | <strong>mac</strong> } ]</p><p><strong>ip macsec add</strong> <em>DEV</em>* * tx sa** { <em>0..3</em> } [ <em>OPTS</em> ] <strong>key</strong> * ID KEY* <br> <strong>ip macsec set</strong> <em>DEV</em>* * tx sa** { <em>0..3</em> } [ <em>OPTS</em> ] <br> <strong>ip macsec del</strong> <em>DEV</em>* * tx sa** { <em>0..3</em> }</p><p><strong>ip macsec add</strong> <em>DEV</em>* * rx** <em>SCI</em> [** on <strong>|</strong> off <em><em>] <br> <strong>ip macsec set</strong> <em>DEV</em></em> * rx</em>* <em>SCI</em> [** on <strong>|</strong> off <em><em>] <br> <strong>ip macsec del</strong> <em>DEV</em></em> * rx</em>* <em>SCI</em></p><p><strong>ip macsec add</strong> <em>DEV</em>* * rx** <em>SCI</em>* * sa** { <em>0..3</em> } [ <em>OPTS</em> ] <strong>key</strong> * ID KEY* <br> <strong>ip macsec set</strong> <em>DEV</em>* * rx** <em>SCI</em>* * sa** { <em>0..3</em> } [ <em>OPTS</em> ] <br> <strong>ip macsec del</strong> <em>DEV</em>* * rx** <em>SCI</em>* * sa** { <em>0..3</em> }</p><p><strong>ip macsec offload</strong> <em>DEV</em> { <strong>off</strong> | <strong>phy</strong> | <strong>mac</strong> }</p><p><strong>ip macsec show</strong> [* DEV *]</p><p><em>OPTS</em> := [ <strong>pn</strong> { <em>1..2^32-1</em> } | <strong>xpn</strong> { <em>1..2^64-1</em> } ] [ <strong>salt</strong> <em>SALT</em> ] [ <strong>ssci</strong> <em>&lt;u32&gt;</em> ] [ <strong>on</strong> | <strong>off</strong> ] <br> <em>SCI</em> := { <strong>sci</strong> <em>&lt;u64&gt;</em> | <strong>port</strong> <em>PORT</em> <strong>address</strong> * &lt;lladdr&gt; * } <br> <em>PORT</em> := { <em>1..2^16-1</em> } <br> <em>SALT</em> := 96-bit hex string</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>ip macsec</strong> commands are used to configure transmit secure associations and receive secure channels and their secure associations on a MACsec device created with the <strong>ip link add</strong> command using the <em>macsec</em> type.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><h3 id="create-a-macsec-device-on-link-eth0-offload-is-disabled-by-default" tabindex="-1">Create a MACsec device on link eth0 (offload is disabled by default) <a class="header-anchor" href="#create-a-macsec-device-on-link-eth0-offload-is-disabled-by-default" aria-label="Permalink to &quot;Create a MACsec device on link eth0 (offload is disabled by default)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip link add link eth0 macsec0 type macsec port 11 encrypt on</span></span></code></pre></div><h3 id="configure-a-secure-association-on-that-device" tabindex="-1">Configure a secure association on that device <a class="header-anchor" href="#configure-a-secure-association-on-that-device" aria-label="Permalink to &quot;Configure a secure association on that device&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 tx sa 0 pn 1024 on key 01 81818181818181818181818181818181</span></span></code></pre></div><h3 id="configure-a-receive-channel" tabindex="-1">Configure a receive channel <a class="header-anchor" href="#configure-a-receive-channel" aria-label="Permalink to &quot;Configure a receive channel&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 rx port 1234 address c6:19:52:8f:e6:a0</span></span></code></pre></div><h3 id="configure-a-receive-association" tabindex="-1">Configure a receive association <a class="header-anchor" href="#configure-a-receive-association" aria-label="Permalink to &quot;Configure a receive association&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 rx port 1234 address c6:19:52:8f:e6:a0 sa 0 pn 1 on key 00 82828282828282828282828282828282</span></span></code></pre></div><h3 id="display-macsec-configuration" tabindex="-1">Display MACsec configuration <a class="header-anchor" href="#display-macsec-configuration" aria-label="Permalink to &quot;Display MACsec configuration&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec show</span></span></code></pre></div><h3 id="configure-offloading-on-an-interface" tabindex="-1">Configure offloading on an interface <a class="header-anchor" href="#configure-offloading-on-an-interface" aria-label="Permalink to &quot;Configure offloading on an interface&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec offload macsec0 phy</span></span></code></pre></div><h3 id="configure-offloading-upon-macsec-device-creation" tabindex="-1">Configure offloading upon MACsec device creation <a class="header-anchor" href="#configure-offloading-upon-macsec-device-creation" aria-label="Permalink to &quot;Configure offloading upon MACsec device creation&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip link add link eth0 macsec0 type macsec port 11 encrypt on offload mac</span></span></code></pre></div><h2 id="extended-packet-number-examples" tabindex="-1">EXTENDED PACKET NUMBER EXAMPLES <a class="header-anchor" href="#extended-packet-number-examples" aria-label="Permalink to &quot;EXTENDED PACKET NUMBER EXAMPLES&quot;">​</a></h2><h3 id="create-a-macsec-device-on-link-eth0-with-enabled-extended-packet-number-offload-is-disabled-by-default" tabindex="-1">Create a MACsec device on link eth0 with enabled extended packet number (offload is disabled by default) <a class="header-anchor" href="#create-a-macsec-device-on-link-eth0-with-enabled-extended-packet-number-offload-is-disabled-by-default" aria-label="Permalink to &quot;Create a MACsec device on link eth0 with enabled extended packet number (offload is disabled by default)&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip link add link eth0 macsec0 type macsec port 11 encrypt on cipher gcm-aes-xpn-128</span></span></code></pre></div><h3 id="configure-a-secure-association-on-that-device-1" tabindex="-1">Configure a secure association on that device <a class="header-anchor" href="#configure-a-secure-association-on-that-device-1" aria-label="Permalink to &quot;Configure a secure association on that device&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 tx sa 0 xpn 1024 on salt 838383838383838383838383 ssci 123 key 01 81818181818181818181818181818181</span></span></code></pre></div><h3 id="configure-a-receive-channel-1" tabindex="-1">Configure a receive channel <a class="header-anchor" href="#configure-a-receive-channel-1" aria-label="Permalink to &quot;Configure a receive channel&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 rx port 11 address c6:19:52:8f:e6:a0</span></span></code></pre></div><h3 id="configure-a-receive-association-1" tabindex="-1">Configure a receive association <a class="header-anchor" href="#configure-a-receive-association-1" aria-label="Permalink to &quot;Configure a receive association&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec add macsec0 rx port 11 address c6:19:52:8f:e6:a0 sa 0 xpn 1 on salt 838383838383838383838383 ssci 123 key 00 82828282828282828282828282828282</span></span></code></pre></div><h3 id="display-macsec-configuration-1" tabindex="-1">Display MACsec configuration <a class="header-anchor" href="#display-macsec-configuration-1" aria-label="Permalink to &quot;Display MACsec configuration&quot;">​</a></h3><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ip macsec show</span></span></code></pre></div><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>This tool can be used to configure the 802.1AE keys of the interface. Note that 802.1AE uses GCM-AES with a initialization vector (IV) derived from the packet number. The same key must not be used with the same IV more than once. Instead, keys must be frequently regenerated and distributed. This tool is thus mostly for debugging and testing, or in combination with a user-space application that reconfigures the keys. It is wrong to just configure the keys statically and assume them to work indefinitely. The suggested and standardized way for key management is 802.1X-2010, which is implemented by wpa_supplicant.</p><h2 id="extended-packet-number-notes" tabindex="-1">EXTENDED PACKET NUMBER NOTES <a class="header-anchor" href="#extended-packet-number-notes" aria-label="Permalink to &quot;EXTENDED PACKET NUMBER NOTES&quot;">​</a></h2><p>Passing cipher <strong>gcm-aes-xpn-128</strong> or <strong>gcm-aes-xpn-256</strong> to <strong>ip link add</strong> command using the <em>macsec</em> type requires using the keyword <strong>&#39;xpn&#39;</strong> instead of <strong>&#39;pn&#39;</strong> in addition to providing a salt using the <strong>&#39;salt&#39;</strong> keyword and ssci using the <strong>&#39;ssci&#39;</strong> keyword when using the <strong>ip macsec</strong> command.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><br> <strong>ip-link</strong>(8) <strong>wpa_supplicant</strong>(8)</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Sabrina Dubroca &lt;sd@queasysnail.net&gt;</p>',46))])}const b=s(c,[["render",l]]);export{f as __pageData,b as default};
